-- suite test: t_kbd (auto-generated by hand, shared boilerplate)
local frame = 0
local t = 0
local function inject(keys)
  for i = 1, #keys do
    emu.write16(0x7E0700 + t, 0x1000 + keys:byte(i), emu.memType.snesMemory)
    t = (t + 2) % 64
  end
  emu.write16(0x7E00D8, t, emu.memType.snesMemory)
end
local function bufhas(str)
  for r = 0, 24 do
    local s = ""
    for c = 0, 79 do
      local ch = emu.read(0x7E1000 + r*160 + c*2, emu.memType.snesMemory)
      if ch < 32 or ch > 126 then ch = 32 end
      s = s .. string.char(ch)
    end
    if s:find(str, 1, true) then return true end
  end
  return false
end
local function bufbyte2(b1, b2)
  for r = 0, 24 do
    for c = 0, 78 do
      if emu.read(0x7E1000 + r*160 + c*2, emu.memType.snesMemory) == b1 and
         emu.read(0x7E1000 + r*160 + (c+1)*2, emu.memType.snesMemory) == b2 then
        return true
      end
    end
  end
  return false
end
local function booted()
  return bufhas("C:\\>")
end

local moved = false
emu.addEventCallback(function()
  frame = frame + 1
  if frame == 1900 then moved = (emu.read16(0x7E00E0, emu.memType.snesMemory) ~= 0) end
  if frame == 2600 then
    local arrow = false
    for i = 0, 31 do
      if emu.read16(0x7E0700 + i*2, emu.memType.snesMemory) == 0x4D00 then arrow = true end
    end
    if moved and arrow then print("RESULT PASS t_kbd")
    else print("RESULT FAIL t_kbd (nav=" .. tostring(moved) .. " arrow=" .. tostring(arrow) .. ")") end
    emu.stop(0)
  end
end, emu.eventType.endFrame)
emu.addEventCallback(function()
  if frame >= 1300 and frame <= 1305 then emu.setInput({ select = true }, 0) end
  if frame >= 1500 and frame <= 1505 then emu.setInput({ down = true }, 0) end
  if frame >= 1700 and frame <= 1705 then emu.setInput({ right = true }, 0) end
  if frame >= 1900 and frame <= 1905 then emu.setInput({ select = true }, 0) end
  if frame >= 2200 and frame <= 2205 then emu.setInput({ right = true }, 0) end
end, emu.eventType.inputPolled)
